const getTrendSlope = `-- name: GetTrendSlope :one
WITH trend_data AS (
    SELECT 
        snapshot_date,
        total_size,
        ROW_NUMBER() OVER (ORDER BY snapshot_date) as x_val,
        COUNT(*) OVER () as n
    FROM usage_snapshots 
    WHERE volume_id = $1 AND snapshot_type = $2 
    AND snapshot_date >= $3 
    ORDER BY snapshot_date
),
slope_calc AS (
    SELECT 
        n,
        SUM(x_val) as sum_x,
        SUM(total_size) as sum_y,
        SUM(x_val * total_size) as sum_xy,
        SUM(x_val * x_val) as sum_x2
    FROM trend_data
    GROUP BY n
)
SELECT 
    CASE 
        WHEN n * sum_x2 - sum_x * sum_x = 0 THEN 0
        ELSE (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x * sum_x)::DOUBLE PRECISION
    END as slope,
    n as data_points
FROM slope_calc
`

type GetTrendSlopeParams struct {
	VolumeID     string    `json:"volume_id"`
	SnapshotType string    `json:"snapshot_type"`
	SnapshotDate time.Time `json:"snapshot_date"`
}

